'use server'

import { revalidatePath } from 'next/cache'
import fs from 'node:fs/promises'
import path from 'node:path'

const DB_PATH = path.join(process.cwd(), 'db.json')

async function getDb() {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8')
    return JSON.parse(data)
  } catch (error) {
    // Fallback if file doesn't exist yet
    return { notifications: false }
  }
}

async function updateDb(data: any) {
  await fs.writeFile(DB_PATH, JSON.stringify(data, null, 2))
}

export async function getNotificationPreference() {
  const db = await getDb()
  return db.notifications
}

export async function toggleNotification() {
  const db = await getDb()

  // Toggle the preference
  db.notifications = !db.notifications

  // Simulate network delay to make the transition noticeable (optional)
  // await new Promise(resolve => setTimeout(resolve, 500))

  await updateDb(db)

  // Revalidate the home page to update the UI without a redirect
  revalidatePath('/')
}

import { getNotificationPreference, toggleNotification } from './actions'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main className="flex min-h-screen flex-col items-center justify-center p-24 font-sans">
      <h1 className="text-4xl font-bold mb-8">User Settings</h1>

      <div className="p-8 border border-gray-200 rounded-xl shadow-lg bg-white text-black max-w-md w-full">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-semibold">Notifications</h2>
          <span className={`px-3 py-1 rounded-full text-sm font-medium ${
            notificationsEnabled 
              ? 'bg-green-100 text-green-800' 
              : 'bg-gray-100 text-gray-800'
          }`}>
            {notificationsEnabled ? 'Enabled' : 'Disabled'}
          </span>
        </div>

        <p className="text-gray-600 mb-6">
          Manage your notification preferences. When enabled, you will receive updates directly to your inbox.
        </p>

        <form action={toggleNotification} className="w-full">
          <button 
            type="submit"
            className={`w-full py-3 px-4 rounded-lg font-medium transition-all duration-200 focus:ring-2 focus:ring-offset-2 focus:outline-none ${
              notificationsEnabled 
                ? 'bg-white border-2 border-red-500 text-red-500 hover:bg-red-50 focus:ring-red-500' 
                : 'bg-blue-600 text-white hover:bg-blue-700 focus:ring-blue-500 shadow-md hover:shadow-lg'
            }`}
          >
            {notificationsEnabled ? 'Turn Notifications Off' : 'Turn Notifications On'}
          </button>
        </form>
      </div>
    </main>
  )
}

import type { Metadata } from "next";
import "./globals.css";

